interface CountryPhoneMetadata {
  code: string;
  prefix: string;
  trunkPrefix?: string;
  minLength: number;
  maxLength: number;
}

const COUNTRY_PHONE_METADATA: Record<string, CountryPhoneMetadata> = {
  ES: { code: "ES", prefix: "34", minLength: 9, maxLength: 9 },
  BE: { code: "BE", prefix: "32", minLength: 9, maxLength: 9 },
  NL: { code: "NL", prefix: "31", minLength: 9, maxLength: 9 },
  DE: { code: "DE", prefix: "49", minLength: 10, maxLength: 11 },
  FR: { code: "FR", prefix: "33", minLength: 9, maxLength: 9 },
  PT: { code: "PT", prefix: "351", minLength: 9, maxLength: 9 },
  IT: { code: "IT", prefix: "39", minLength: 9, maxLength: 10 },
  GB: { code: "GB", prefix: "44", trunkPrefix: "0", minLength: 10, maxLength: 10 },
  PL: { code: "PL", prefix: "48", minLength: 9, maxLength: 9 },
  RO: { code: "RO", prefix: "40", minLength: 9, maxLength: 9 },
};

interface NormalizeResult {
  valid: boolean;
  /** Canonico E.164 CON '+' inicial (ej. "+34612345678"). */
  e164?: string;
  countryCode?: string;
  error?: string;
}

/**
 * Normaliza un numero nacional o internacional a E.164 canonico con '+'.
 * - Elimina todo lo que no sea digito.
 * - Si ya incluye prefijo internacional, lo conserva.
 * - Si empieza con el trunk prefix nacional (ej. 0 en UK), lo elimina.
 * - Valida longitud minima/maxima para el pais.
 */
function normalizeToE164(
  countryCode: string,
  nationalNumber: string,
): NormalizeResult {
  const meta = COUNTRY_PHONE_METADATA[countryCode.toUpperCase()];
  if (!meta) {
    return { valid: false, error: `unsupported_country: ${countryCode}` };
  }

  let digits = nationalNumber.replace(/\D/g, "");

  // Si ya incluye prefijo internacional, quitarlo para tratar como nacional
  if (digits.startsWith(meta.prefix)) {
    digits = digits.slice(meta.prefix.length);
  }

  // Quitar trunk prefix nacional si existe
  if (meta.trunkPrefix && digits.startsWith(meta.trunkPrefix)) {
    digits = digits.slice(meta.trunkPrefix.length);
  }

  if (digits.length < meta.minLength || digits.length > meta.maxLength) {
    return {
      valid: false,
      error: `invalid_length: expected ${meta.minLength}-${meta.maxLength}, got ${digits.length}`,
    };
  }

  return {
    valid: true,
    e164: `+${meta.prefix}${digits}`,
    countryCode: meta.code,
  };
}

/**
 * Enmascara un E.164 para auditoria/logs: conserva '+' y el prefijo de pais
 * (2-3 digitos) y los 3 ultimos digitos; el resto se sustituye por '*'.
 * Ej.: "+34612345678" -> "+34******678". NUNCA devuelve el numero completo.
 */
function maskE164(e164: string): string {
  if (!e164 || e164.length < 7) return "***";
  // Prefijo de pais conocido si es posible; si no, 2 digitos tras el '+'.
  const digits = e164.replace(/\D/g, "");
  let prefixLen = 2;
  for (const meta of Object.values(COUNTRY_PHONE_METADATA)) {
    if (digits.startsWith(meta.prefix)) {
      prefixLen = meta.prefix.length;
      break;
    }
  }
  const head = `+${digits.slice(0, prefixLen)}`;
  const tail = digits.slice(-3);
  return `${head}******${tail}`;
}

/**
 * Genera un codigo OTP de 6 digitos con CSPRNG (crypto.getRandomValues).
 * Nunca usar Math.random para secretos.
 */
function generateOtpCode(): string {
  const buf = new Uint32Array(1);
  crypto.getRandomValues(buf);
  return (100000 + (buf[0] % 900000)).toString();
}

function formatE164ForDisplay(e164: string, countryCode: string): string {
  const meta = COUNTRY_PHONE_METADATA[countryCode.toUpperCase()];
  const digits = e164.replace(/\D/g, "");
  if (!meta || !digits.startsWith(meta.prefix)) return e164;
  const national = digits.slice(meta.prefix.length);
  return `+${meta.prefix} ${national}`;
}


const PHONE_EVENT_TYPES = [
  "phone_added",
  "phone_changed",
  "verification_started",
  "verification_failed",
  "phone_verified",
  "whatsapp_opt_in_changed",
] as const;

type PhoneEventType = (typeof PHONE_EVENT_TYPES)[number];

interface PhoneEventInput {
  userId: string;
  event: PhoneEventType;
  /** E.164 completo: se enmascara antes de persistir. */
  phoneE164?: string | null;
  /** Solo datos no sensibles (reason, scope, valores booleanos). */
  metadata?: Record<string, unknown>;
}

// deno-lint-ignore no-explicit-any
async function recordPhoneEvent(
  supabase: SupabaseClient<any, any, any>,
  input: PhoneEventInput,
): Promise<void> {
  try {
    const { error } = await supabase
      .from("app_14da0f1941_phone_events")
      .insert({
        user_id: input.userId,
        event: input.event,
        phone_masked: input.phoneE164 ? maskE164(input.phoneE164) : null,
        metadata: input.metadata ?? {},
      });
    if (error) {
      console.warn(`[phone-events] audit insert failed for event=${input.event}: ${error.message}`);
    }
  } catch (err) {
    console.warn(`[phone-events] audit insert threw for event=${input.event}`);
  }
}


const CONSENT_VERSION = "wa-consent-v1";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

function json(body: Record<string, unknown>, status: number): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
  const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

  const supabase = createClient(supabaseUrl, serviceKey, {
    auth: { autoRefreshToken: false, persistSession: false },
  });

  const authHeader = req.headers.get("authorization");
  if (!authHeader) {
    return json({ error: "Unauthorized" }, 401);
  }

  const { data: { user }, error: userError } = await supabase.auth.getUser(authHeader.replace("Bearer ", ""));
  if (userError || !user) {
    return json({ error: "Unauthorized" }, 401);
  }

  let body: {
    service_opt_in?: boolean;
    job_alerts_opt_in?: boolean;
    marketing_opt_in?: boolean;
  } = {};
  try {
    body = await req.json();
  } catch {
    // ignore
  }

  const wantsTrue = [body.service_opt_in, body.job_alerts_opt_in, body.marketing_opt_in]
    .some((v) => v === true);
  const anyProvided = [body.service_opt_in, body.job_alerts_opt_in, body.marketing_opt_in]
    .some((v) => typeof v === "boolean");

  if (!anyProvided) {
    return json({ error: "no_consent_fields" }, 400);
  }

  const { data: profile, error: profileError } = await supabase
    .from("app_14da0f1941_profiles")
    .select("user_id, phone_e164, phone_verified, whatsapp_service_opt_in, whatsapp_job_alerts_opt_in, whatsapp_marketing_opt_in")
    .eq("user_id", user.id)
    .maybeSingle();

  if (profileError) {
    return json({ error: profileError.message }, 500);
  }

  if (!profile || !profile.phone_e164) {
    return json({ error: "phone_required" }, 400);
  }

  if (wantsTrue && !profile.phone_verified) {
    return json({ error: "phone_not_verified" }, 400);
  }

  const next = {
    whatsapp_service_opt_in: typeof body.service_opt_in === "boolean"
      ? body.service_opt_in
      : profile.whatsapp_service_opt_in,
    whatsapp_job_alerts_opt_in: typeof body.job_alerts_opt_in === "boolean"
      ? body.job_alerts_opt_in
      : profile.whatsapp_job_alerts_opt_in,
    whatsapp_marketing_opt_in: typeof body.marketing_opt_in === "boolean"
      ? body.marketing_opt_in
      : profile.whatsapp_marketing_opt_in,
  };

  const now = new Date().toISOString();
  const anyOn = next.whatsapp_service_opt_in || next.whatsapp_job_alerts_opt_in || next.whatsapp_marketing_opt_in;
  const wasOn = profile.whatsapp_service_opt_in || profile.whatsapp_job_alerts_opt_in || profile.whatsapp_marketing_opt_in;

  const update: Record<string, unknown> = {
    ...next,
    whatsapp_consent_at: now,
    whatsapp_consent_version: CONSENT_VERSION,
  };

  // Revocacion efectiva: todos a false habiendo habido algun opt-in activo.
  // FIX L3: whatsapp_opted_out_at es la fecha de la ULTIMA retirada efectiva
  // y se CONSERVA al reactivar un opt-in (semantica historica, no de estado).
  // El estado actual lo dan siempre los tres flags booleanos; opted_out_at
  // solo registra cuando ocurrio la ultima revocacion (auditable, GDPR).
  if (!anyOn && wasOn) {
    update.whatsapp_opted_out_at = now;
  }

  const { error: updateError } = await supabase
    .from("app_14da0f1941_profiles")
    .update(update)
    .eq("user_id", user.id);

  if (updateError) {
    return json({ error: updateError.message }, 500);
  }

  await recordPhoneEvent(supabase, {
    userId: user.id,
    event: "whatsapp_opt_in_changed",
    phoneE164: profile.phone_e164,
    metadata: {
      service: next.whatsapp_service_opt_in,
      job_alerts: next.whatsapp_job_alerts_opt_in,
      marketing: next.whatsapp_marketing_opt_in,
      consent_version: CONSENT_VERSION,
      revoked: !anyOn && wasOn,
    },
  });

  return json({ ok: true, ...next, consent_version: CONSENT_VERSION }, 200);
});
